-- ----------------------------------------------------------------------------
-- sup:CustomerSuccessManager  (Customer, Canonical)
-- An internal individual assigned to accounts considered valuable, with
-- responsibility for adoption, retention and relationship health. Unlike the
-- sales representative, CSM assignment is conditional — most accounts do not
-- have one.
-- Identity: The CRM user ID is authoritative.
-- ----------------------------------------------------------------------------
CREATE TABLE customer_success_manager (
    csm_id VARCHAR(255) NOT NULL,  -- csmId (string, required): CRM user ID
    is_active BOOLEAN NOT NULL,  -- isActive (boolean, required): Currently holding the role
    CONSTRAINT pk_customer_success_manager PRIMARY KEY (csm_id)
);

-- ----------------------------------------------------------------------------
-- sup:Partner  (Customer, Proposed)
-- An Independent Software Vendor (ISV) or partner organization that
-- represents one or more accounts. Partners can submit and manage support
-- tickets on behalf of the customers they represent.
-- Identity: The CRM partner ID is authoritative.
-- ----------------------------------------------------------------------------
CREATE TABLE partner (
    partner_id VARCHAR(255) NOT NULL,  -- partnerId (string, required): CRM primary key for the partner
    partner_name VARCHAR(255) NOT NULL,  -- partnerName (string, required): Legal or trading name of the partner
    partnership_level VARCHAR(255),  -- partnershipLevel (string): E.g., Gold, Silver
    CONSTRAINT pk_partner PRIMARY KEY (partner_id)
);

-- ----------------------------------------------------------------------------
-- sup:Region  (Customer, Canonical)
-- A geographic territory used to distribute accounts and assign commercial
-- and support coverage. Regions determine which sales representative owns an
-- account and which support team's working hours apply to its tickets.
-- Identity: Natural key: the region code (EMEA, NA, APAC, LATAM). Codes are
-- stable and never reused.
-- ----------------------------------------------------------------------------
CREATE TABLE region (
    region_code VARCHAR(255) NOT NULL,  -- regionCode (string, required): Short stable code
    region_name VARCHAR(255) NOT NULL,  -- regionName (string, required): Display name
    time_zone_range VARCHAR(255),  -- timeZoneRange (string): Used to derive support coverage hours
    CONSTRAINT pk_region PRIMARY KEY (region_code)
);

-- ----------------------------------------------------------------------------
-- sup:SalesRepresentative  (Customer, Canonical)
-- An internal individual who commercially owns a set of accounts. Assignment
-- is driven by region: an account's sales representative is drawn from the
-- representatives covering that account's region.
-- Identity: The CRM user ID is authoritative.
-- ----------------------------------------------------------------------------
CREATE TABLE sales_representative (
    rep_id VARCHAR(255) NOT NULL,  -- repId (string, required): CRM user ID
    is_active BOOLEAN NOT NULL,  -- isActive (boolean, required): Currently holding the role
    CONSTRAINT pk_sales_representative PRIMARY KEY (rep_id)
);

-- ----------------------------------------------------------------------------
-- sup:SupportEntitlement  (Customer, Canonical)
-- The tier of support service an account is entitled to receive. The tier
-- governs response time targets, escalation rights and channel access.
-- Entitlement is a property of the account, not of an individual ticket or
-- license.
-- Identity: Natural key: the canonical tier code (STANDARD, PREMIUM).
-- Entitlement is a controlled vocabulary, not a per-account record — the
-- per-account fact is the hasEntitlement link, and its effective dates live
-- on the link.
-- ----------------------------------------------------------------------------
CREATE TABLE support_entitlement (
    tier_code VARCHAR(32) NOT NULL,  -- tierCode (enum(STANDARD, PREMIUM), required): Canonical code
    tier_rank INTEGER NOT NULL,  -- tierRank (integer, required): Higher = more entitled. Standard 1, Premium 2
    grants_escalation_right BOOLEAN,  -- grantsEscalationRight (boolean, required): Whether the tier may demand escalation | NULL allowed while unconfirmed
    response_target_hours INTEGER,  -- responseTargetHours (integer): Varies by severity — see OQ-06
    CONSTRAINT pk_support_entitlement PRIMARY KEY (tier_code),
    CONSTRAINT ck_support_entitlement_tier_code CHECK (tier_code IN ('STANDARD', 'PREMIUM')),
    CONSTRAINT ck_support_entitlement_c12 CHECK (grants_escalation_right = FALSE OR tier_code = 'PREMIUM')
);

-- ----------------------------------------------------------------------------
-- sup:Account  (Customer, Canonical)
-- A commercial customer organization that holds one or more licenses to our
-- products and is entitled to receive support. The Account is the unit that
-- entitlement, licensing, regional assignment and commercial ownership all
-- hang off. An Account is an organization, never an individual person — the
-- people at an account are modelled as sup:Contact.
-- Identity: The CRM account ID is authoritative. Where an organization
-- exists as multiple account records across brand-specific CRM orgs, they
-- are the same sup:Account only if they share a resolved parent organization
-- ID. See OQ-03 — account de-duplication across brand orgs is unresolved.
-- ----------------------------------------------------------------------------
CREATE TABLE account (
    account_id VARCHAR(255) NOT NULL,  -- accountId (string, required): CRM primary key
    account_name VARCHAR(255) NOT NULL,  -- accountName (string, required): Legal or trading name
    is_strategic BOOLEAN,  -- isStrategic (boolean): Drives CSM eligibility — see C-08
    account_status VARCHAR(32) NOT NULL,  -- accountStatus (enum(Active, Lapsed, Churned), required): Lapsed = no active license
    created_at DATE NOT NULL,  -- createdAt (date, required): First became a customer
    region_code VARCHAR(255) NOT NULL,  -- isLocatedIn -> Region (1..1)
    tier_code VARCHAR(32) NOT NULL,  -- hasEntitlement -> SupportEntitlement (1..1)
    rep_id VARCHAR(255) NOT NULL,  -- hasSalesRep -> SalesRepresentative (1..1)
    csm_id VARCHAR(255),  -- hasCSM -> CustomerSuccessManager (0..1)
    CONSTRAINT pk_account PRIMARY KEY (account_id),
    CONSTRAINT fk_account_is_located_in FOREIGN KEY (region_code) REFERENCES region (region_code),
    CONSTRAINT fk_account_has_entitlement FOREIGN KEY (tier_code) REFERENCES support_entitlement (tier_code),
    CONSTRAINT fk_account_has_sales_rep FOREIGN KEY (rep_id) REFERENCES sales_representative (rep_id),
    CONSTRAINT fk_account_has_csm FOREIGN KEY (csm_id) REFERENCES customer_success_manager (csm_id),
    CONSTRAINT ck_account_account_status CHECK (account_status IN ('Active', 'Lapsed', 'Churned'))
);

-- ----------------------------------------------------------------------------
-- sup:Contact  (Customer, Canonical)
-- An individual person at a customer account who is authorised to raise
-- support tickets and use self-service tools. A Contact is a person in their
-- capacity as a customer representative. Internal staff are modelled as
-- sup:SupportAgent, sup:SalesRepresentative or sup:CustomerSuccessManager.
-- Identity: CRM contact ID is authoritative.
-- ----------------------------------------------------------------------------
CREATE TABLE contact (
    contact_id VARCHAR(255) NOT NULL,  -- contactId (string, required): CRM primary key
    email_address VARCHAR(255) NOT NULL,  -- emailAddress (string, required): Also the join key to ticket submissions
    is_support_authorised BOOLEAN NOT NULL,  -- isSupportAuthorised (boolean, required): Whether this contact may open tickets
    is_primary BOOLEAN,  -- isPrimary (boolean): Primary technical contact for the account
    account_id VARCHAR(255) NOT NULL,  -- worksFor -> Account (1..1)
    CONSTRAINT pk_contact PRIMARY KEY (contact_id),
    CONSTRAINT fk_contact_works_for FOREIGN KEY (account_id) REFERENCES account (account_id)
);

-- ----------------------------------------------------------------------------
-- sup:Product  (Product, Canonical)
-- A software product that customers license and raise support tickets about.
-- The Product is what a license grants access to, what a ticket concerns,
-- and what documentation describes. It is the join point between the
-- commercial, support and knowledge parts of the model.
-- Identity: The licensing system product ID is authoritative. Version is not
-- part of identity — a product and its versions are the same product.
-- Version-specific facts would need sup:ProductVersion, which is not
-- modelled (OQ-15).
-- ----------------------------------------------------------------------------
CREATE TABLE product (
    product_id VARCHAR(255) NOT NULL,  -- productId (string, required): Licensing system key
    product_name VARCHAR(255) NOT NULL,  -- productName (string, required)
    current_version VARCHAR(255),  -- currentVersion (string): Latest generally available release
    lifecycle_status VARCHAR(32) NOT NULL,  -- lifecycleStatus (enum(GA, Maintenance, EndOfLife), required): EOL drives documentation retirement
    end_of_life_date DATE,  -- endOfLifeDate (date): Required when lifecycleStatus = EndOfLife
    uses_platinum_naming BOOLEAN NOT NULL,  -- usesPlatinumNaming (boolean, required): True where Premium Support is sold as Platinum Support — alias anchor for EQ-02
    severity_term_used VARCHAR(32) NOT NULL,  -- severityTermUsed (enum(Severity, Priority), required): Which word this product's support uses — alias anchor for EQ-03
    documentation_root_url VARCHAR(2048),  -- documentationRootUrl (string): Entry point for this product's KB
    CONSTRAINT pk_product PRIMARY KEY (product_id),
    CONSTRAINT ck_product_lifecycle_status CHECK (lifecycle_status IN ('GA', 'Maintenance', 'EndOfLife')),
    CONSTRAINT ck_product_severity_term_used CHECK (severity_term_used IN ('Severity', 'Priority')),
    CONSTRAINT ck_product_c22 CHECK (lifecycle_status <> 'EndOfLife' OR end_of_life_date IS NOT NULL)
);

-- ----------------------------------------------------------------------------
-- sup:License  (Customer, Canonical)
-- A grant of the right to use a specific product, held by a specific
-- account, for a defined period and quantity. The license is what makes a
-- support request legitimate: an account may only raise tickets about
-- products it is licensed for.
-- Identity: Composite: accountId + productId + startDate. A renewal produces
-- a new License instance rather than mutating the existing one, so that
-- historical coverage questions stay answerable.
-- ----------------------------------------------------------------------------
CREATE TABLE license (
    account_id VARCHAR(255) NOT NULL,  -- isHeldBy -> Account (1..1)
    product_id VARCHAR(255) NOT NULL,  -- grantsAccessTo -> Product (1..1)
    start_date DATE NOT NULL,  -- startDate (date, required)
    license_key VARCHAR(255) NOT NULL,  -- licenseKey (string, required): Licensing system identifier
    seat_count INTEGER,  -- seatCount (integer): Null for unlimited or site licenses
    end_date DATE,  -- endDate (date): Null = perpetual
    is_active BOOLEAN NOT NULL,  -- isActive (boolean, required): Derived: endDate is null or in the future
    license_type VARCHAR(32) NOT NULL,  -- licenseType (enum(Subscription, Perpetual, Trial, NFR), required)
    tier_code VARCHAR(32) NOT NULL,  -- isBoundTo -> SupportEntitlement (1..1)
    CONSTRAINT pk_license PRIMARY KEY (account_id, product_id, start_date),
    CONSTRAINT fk_license_is_held_by FOREIGN KEY (account_id) REFERENCES account (account_id),
    CONSTRAINT fk_license_grants_access_to FOREIGN KEY (product_id) REFERENCES product (product_id),
    CONSTRAINT fk_license_is_bound_to FOREIGN KEY (tier_code) REFERENCES support_entitlement (tier_code),
    CONSTRAINT ck_license_license_type CHECK (license_type IN ('Subscription', 'Perpetual', 'Trial', 'NFR')),
    CONSTRAINT ck_license_c13 CHECK (end_date IS NULL OR end_date > start_date)
);

-- ----------------------------------------------------------------------------
-- sup:CRM  (Support, Canonical)
-- A customer relationship management system that records tickets. Each
-- distinct CRM instance is a distinct instance of this class, because each
-- carries its own ticket numbering, its own user records, and — critically —
-- its own vocabulary.
-- Identity: Natural key: the system code (e.g. SF_EMEA, SF_AMER). Each org
-- is a separate instance even when several orgs run on the same platform,
-- because the ID spaces and the vocabulary do not carry across.
-- ----------------------------------------------------------------------------
CREATE TABLE crm (
    system_code VARCHAR(255) NOT NULL,  -- systemCode (string, required): Stable short code
    system_name VARCHAR(255) NOT NULL,  -- systemName (string, required)
    ticket_term_used VARCHAR(32),  -- ticketTermUsed (enum(Ticket, Case), required): The alias anchor for EQ-01 | NULL allowed while unconfirmed (OQ-50)
    is_authoritative BOOLEAN,  -- isAuthoritative (boolean, required): Whether this system is the source of truth or a mirror | NULL allowed while unconfirmed (OQ-50)
    CONSTRAINT pk_crm PRIMARY KEY (system_code),
    CONSTRAINT ck_crm_ticket_term_used CHECK (ticket_term_used IN ('Ticket', 'Case'))
);

-- ----------------------------------------------------------------------------
-- sup:SeverityLevel  (Support, Canonical)
-- The graded measure of a ticket's business impact and urgency, used to set
-- response expectations and routing. Every ticket has exactly one.
-- Identity: Natural key: the canonical level code S1–S4. All product-
-- specific labels (P1, Critical, High, 1 - Urgent) resolve to one of these
-- four.
-- ----------------------------------------------------------------------------
CREATE TABLE severity_level (
    level_code VARCHAR(32) NOT NULL,  -- levelCode (enum(S1, S2, S3, S4), required): Canonical code
    level_rank INTEGER NOT NULL,  -- levelRank (integer, required): 1 = most severe. Lower rank = more urgent
    level_name VARCHAR(255) NOT NULL,  -- levelName (string, required): Canonical display name
    definition TEXT NOT NULL,  -- definition (text, required): The impact test that puts a ticket at this level
    CONSTRAINT pk_severity_level PRIMARY KEY (level_code),
    CONSTRAINT ck_severity_level_level_code CHECK (level_code IN ('S1', 'S2', 'S3', 'S4'))
);

-- ----------------------------------------------------------------------------
-- sup:SLA  (Support, Proposed)
-- The Service Level Agreement that governs a ticket, dictating the target
-- times for response and resolution. An SLA is determined by the severity of
-- the ticket and the entitlement of the customer account. Support agents are
-- measured against their ability to meet these SLA targets.
-- Identity: A composite of severityLevel + entitlementTier.
-- ----------------------------------------------------------------------------
CREATE TABLE sla (
    level_code VARCHAR(32) NOT NULL,  -- identity: severityLevel -> SeverityLevel
    tier_code VARCHAR(32) NOT NULL,  -- identity: entitlementTier -> SupportEntitlement
    sla_name VARCHAR(255) NOT NULL,  -- slaName (string, required): E.g., "Premium S1"
    target_response_minutes INTEGER NOT NULL,  -- targetResponseMinutes (integer, required)
    target_resolution_minutes INTEGER NOT NULL,  -- targetResolutionMinutes (integer, required)
    CONSTRAINT pk_sla PRIMARY KEY (level_code, tier_code),
    CONSTRAINT fk_sla_identity_severity_level FOREIGN KEY (level_code) REFERENCES severity_level (level_code),
    CONSTRAINT fk_sla_identity_support_entitlement FOREIGN KEY (tier_code) REFERENCES support_entitlement (tier_code)
);

-- ----------------------------------------------------------------------------
-- sup:SupportAgent  (Support, Canonical)
-- An internal member of the support organization who is assigned tickets,
-- resolves them using documentation, and escalates to development when a
-- ticket is caused by a defect or requires new functionality.
-- Identity: The CRM user ID is authoritative. Agents appearing in more than
-- one CRM are matched on corporate email.
-- ----------------------------------------------------------------------------
CREATE TABLE support_agent (
    agent_id VARCHAR(255) NOT NULL,  -- agentId (string, required): CRM user ID
    tier VARCHAR(32),  -- tier (enum(T1, T2, T3)): Support tier, where the team is tiered
    is_active BOOLEAN NOT NULL,  -- isActive (boolean, required): Currently holding the role
    CONSTRAINT pk_support_agent PRIMARY KEY (agent_id),
    CONSTRAINT ck_support_agent_tier CHECK (tier IN ('T1', 'T2', 'T3'))
);

-- ----------------------------------------------------------------------------
-- sup:Ticket  (Support, Canonical)
-- A single recorded request for support from a customer account, tracked
-- from submission to resolution. One ticket represents one customer problem.
-- It is owned by exactly one account, assigned to at most one agent at a
-- time, carries exactly one severity, is governed by exactly one SLA, and
-- may be escalated to development. It may be submitted by a Contact at the
-- account or, where the customer buys through one, by a Partner acting on
-- the account's behalf.
-- Identity: The CRM ticket/case number is authoritative. Ticket numbers are
-- unique within a CRM but not across CRMs — a fully qualified ticket
-- identity is systemCode + ticketNumber. This is a real collision risk in
-- reporting.
-- ----------------------------------------------------------------------------
CREATE TABLE ticket (
    system_code VARCHAR(255) NOT NULL,  -- recordedIn -> CRM (1..1)
    ticket_number VARCHAR(255) NOT NULL,  -- ticketNumber (string, required): CRM case number
    subject VARCHAR(255) NOT NULL,  -- subject (string, required)
    status VARCHAR(32) NOT NULL,  -- status (enum(New, Open, Pending, Escalated, Resolved, Closed), required)
    opened_at TIMESTAMP NOT NULL,  -- openedAt (datetime, required)
    resolved_at TIMESTAMP,  -- resolvedAt (datetime): Required when status is Resolved or Closed
    resolution_summary TEXT,  -- resolutionSummary (text)
    partner_id VARCHAR(255),  -- submittedByPartner -> Partner (0..1)
    account_id VARCHAR(255) NOT NULL,  -- belongsTo -> Account (1..1)
    contact_id VARCHAR(255),  -- submittedBy -> Contact (0..1)
    product_id VARCHAR(255) NOT NULL,  -- concerns -> Product (1..1)
    agent_id VARCHAR(255),  -- assignedTo -> SupportAgent (0..1)
    level_code VARCHAR(32) NOT NULL,  -- hasSeverity -> SeverityLevel (1..1)
    sla_level_code VARCHAR(32) NOT NULL,  -- isGovernedBy -> SLA (1..1)
    sla_tier_code VARCHAR(32) NOT NULL,  -- isGovernedBy -> SLA (1..1)
    CONSTRAINT pk_ticket PRIMARY KEY (system_code, ticket_number),
    CONSTRAINT fk_ticket_recorded_in FOREIGN KEY (system_code) REFERENCES crm (system_code),
    CONSTRAINT fk_ticket_submitted_by_partner FOREIGN KEY (partner_id) REFERENCES partner (partner_id),
    CONSTRAINT fk_ticket_belongs_to FOREIGN KEY (account_id) REFERENCES account (account_id),
    CONSTRAINT fk_ticket_submitted_by FOREIGN KEY (contact_id) REFERENCES contact (contact_id),
    CONSTRAINT fk_ticket_concerns FOREIGN KEY (product_id) REFERENCES product (product_id),
    CONSTRAINT fk_ticket_assigned_to FOREIGN KEY (agent_id) REFERENCES support_agent (agent_id),
    CONSTRAINT fk_ticket_has_severity FOREIGN KEY (level_code) REFERENCES severity_level (level_code),
    CONSTRAINT fk_ticket_is_governed_by FOREIGN KEY (sla_level_code, sla_tier_code) REFERENCES sla (level_code, tier_code),
    CONSTRAINT ck_ticket_status CHECK (status IN ('New', 'Open', 'Pending', 'Escalated', 'Resolved', 'Closed')),
    CONSTRAINT ck_ticket_c24 CHECK ((status NOT IN ('Resolved', 'Closed') OR resolved_at IS NOT NULL) AND (resolved_at IS NULL OR resolved_at >= opened_at))
);

-- ----------------------------------------------------------------------------
-- sup:JiraIssue  (Engineering, Canonical)
-- A unit of engineering work tracked in Jira, created as the result of a
-- support escalation, representing either a defect to fix or a capability to
-- build. Its key is the identifier that gets associated back to the
-- originating ticket.
-- Identity: The Jira issue key (e.g. PROJ-1234) is authoritative and
-- globally unique.
-- ----------------------------------------------------------------------------
CREATE TABLE jira_issue (
    issue_key VARCHAR(255) NOT NULL,  -- issueKey (string, required): e.g. PROJ-1234
    issue_type VARCHAR(32) NOT NULL,  -- issueType (enum(Bug, Enhancement), required): Matches escalation type at creation
    issue_status VARCHAR(255) NOT NULL,  -- issueStatus (string, required): Jira workflow status — varies by project
    is_resolved BOOLEAN NOT NULL,  -- isResolved (boolean, required): Normalised across the varying workflows
    fix_version VARCHAR(255),  -- fixVersion (string): Release that carries the fix
    created_at TIMESTAMP NOT NULL,  -- createdAt (datetime, required)
    CONSTRAINT pk_jira_issue PRIMARY KEY (issue_key),
    CONSTRAINT ck_jira_issue_issue_type CHECK (issue_type IN ('Bug', 'Enhancement'))
);

-- ----------------------------------------------------------------------------
-- sup:Escalation  (Support, Canonical)
-- The act of a support agent referring a ticket to development because it
-- has been identified as a defect or as a request for new functionality. The
-- Escalation produces a Jira issue and is the only legitimate way a Jira ID
-- becomes associated with a ticket.
-- Identity: Surrogate: generated UUID. There is no natural key — the same
-- ticket can be escalated more than once, and the same Jira issue can
-- receive escalations from many tickets.
-- ----------------------------------------------------------------------------
CREATE TABLE escalation (
    escalation_id VARCHAR(36) NOT NULL,  -- escalationId (uuid, required): Surrogate key
    escalation_type VARCHAR(32) NOT NULL,  -- escalationType (enum(Bug, Enhancement), required): The agent's classification
    escalated_at TIMESTAMP NOT NULL,  -- escalatedAt (datetime, required)
    justification TEXT NOT NULL,  -- justification (text, required): Why the agent judged this a dev matter
    was_accepted BOOLEAN,  -- wasAccepted (boolean): Whether development accepted the classification
    reproduction_steps TEXT,  -- reproductionSteps (text): Expected for Bug type
    system_code VARCHAR(255) NOT NULL,  -- originatesFrom -> Ticket (1..1)
    ticket_number VARCHAR(255) NOT NULL,  -- originatesFrom -> Ticket (1..1)
    agent_id VARCHAR(255) NOT NULL,  -- escalatedBy -> SupportAgent (1..1)
    issue_key VARCHAR(255) NOT NULL,  -- producedIssue -> JiraIssue (1..1)
    CONSTRAINT pk_escalation PRIMARY KEY (escalation_id),
    CONSTRAINT fk_escalation_originates_from FOREIGN KEY (system_code, ticket_number) REFERENCES ticket (system_code, ticket_number),
    CONSTRAINT fk_escalation_escalated_by FOREIGN KEY (agent_id) REFERENCES support_agent (agent_id),
    CONSTRAINT fk_escalation_produced_issue FOREIGN KEY (issue_key) REFERENCES jira_issue (issue_key),
    CONSTRAINT ck_escalation_escalation_type CHECK (escalation_type IN ('Bug', 'Enhancement'))
);

-- ----------------------------------------------------------------------------
-- sup:Documentation  (Knowledge, Canonical)
-- Published product documentation and knowledge base content that support
-- agents consult to resolve tickets. One instance is one published unit — an
-- article or page — identified by its URL.
-- Identity: The published URL is authoritative. Where content exists at
-- several URLs (localised or mirrored), the canonical URL is the identity
-- and the others are recorded as aliases.
-- ----------------------------------------------------------------------------
CREATE TABLE documentation (
    article_url VARCHAR(2048) NOT NULL,  -- articleUrl (string, required): Canonical published URL — the identity
    title VARCHAR(255) NOT NULL,  -- title (string, required)
    last_reviewed_at DATE,  -- lastReviewedAt (date): Staleness signal for C-40
    is_public BOOLEAN NOT NULL,  -- isPublic (boolean, required): Whether customers can reach it
    product_id VARCHAR(255),  -- describes -> Product (1..1); nullable because C-55 is Soft
    CONSTRAINT pk_documentation PRIMARY KEY (article_url),
    CONSTRAINT fk_documentation_describes FOREIGN KEY (product_id) REFERENCES product (product_id)
);

-- ----------------------------------------------------------------------------
-- Region isCoveredBy SalesRepresentative  (1..*); inverse covers (1..*)
-- Many-to-many, so it needs its own table.
-- ----------------------------------------------------------------------------
CREATE TABLE region_is_covered_by_sales_representative (
    region_code VARCHAR(255) NOT NULL,  -- -> region.region_code
    rep_id VARCHAR(255) NOT NULL,  -- -> sales_representative.rep_id
    CONSTRAINT pk_region_is_covered_by_sales_representative PRIMARY KEY (region_code, rep_id),
    CONSTRAINT fk_region_is_covered_by_sales_representative_from FOREIGN KEY (region_code) REFERENCES region (region_code),
    CONSTRAINT fk_region_is_covered_by_sales_representative_to FOREIGN KEY (rep_id) REFERENCES sales_representative (rep_id)
);

-- ----------------------------------------------------------------------------
-- Partner represents Account  (0..*); inverse isRepresentedBy (0..*)
-- Many-to-many, so it needs its own table.
-- ----------------------------------------------------------------------------
CREATE TABLE partner_represents_account (
    partner_id VARCHAR(255) NOT NULL,  -- -> partner.partner_id
    account_id VARCHAR(255) NOT NULL,  -- -> account.account_id
    CONSTRAINT pk_partner_represents_account PRIMARY KEY (partner_id, account_id),
    CONSTRAINT fk_partner_represents_account_from FOREIGN KEY (partner_id) REFERENCES partner (partner_id),
    CONSTRAINT fk_partner_represents_account_to FOREIGN KEY (account_id) REFERENCES account (account_id)
);

-- ----------------------------------------------------------------------------
-- Ticket resolvedUsing Documentation  (0..*); inverse resolves (0..*)
-- Many-to-many, so it needs its own table.
-- Note: May be aspirational — OQ-30
-- ----------------------------------------------------------------------------
CREATE TABLE ticket_resolved_using_documentation (
    system_code VARCHAR(255) NOT NULL,  -- -> ticket.system_code
    ticket_number VARCHAR(255) NOT NULL,  -- -> ticket.ticket_number
    article_url VARCHAR(2048) NOT NULL,  -- -> documentation.article_url
    CONSTRAINT pk_ticket_resolved_using_documentation PRIMARY KEY (system_code, ticket_number, article_url),
    CONSTRAINT fk_ticket_resolved_using_documentation_from FOREIGN KEY (system_code, ticket_number) REFERENCES ticket (system_code, ticket_number),
    CONSTRAINT fk_ticket_resolved_using_documentation_to FOREIGN KEY (article_url) REFERENCES documentation (article_url)
);

-- ----------------------------------------------------------------------------
-- SupportAgent specialisesIn Product  (0..*); inverse isSupportedBy (0..*)
-- Many-to-many, so it needs its own table.
-- Note: Source may be informal — OQ-23
-- ----------------------------------------------------------------------------
CREATE TABLE support_agent_specialises_in_product (
    agent_id VARCHAR(255) NOT NULL,  -- -> support_agent.agent_id
    product_id VARCHAR(255) NOT NULL,  -- -> product.product_id
    CONSTRAINT pk_support_agent_specialises_in_product PRIMARY KEY (agent_id, product_id),
    CONSTRAINT fk_support_agent_specialises_in_product_from FOREIGN KEY (agent_id) REFERENCES support_agent (agent_id),
    CONSTRAINT fk_support_agent_specialises_in_product_to FOREIGN KEY (product_id) REFERENCES product (product_id)
);

-- ----------------------------------------------------------------------------
-- SupportAgent consults Documentation  (0..*); inverse isConsultedBy (0..*)
-- Many-to-many, so it needs its own table.
-- ----------------------------------------------------------------------------
CREATE TABLE support_agent_consults_documentation (
    agent_id VARCHAR(255) NOT NULL,  -- -> support_agent.agent_id
    article_url VARCHAR(2048) NOT NULL,  -- -> documentation.article_url
    CONSTRAINT pk_support_agent_consults_documentation PRIMARY KEY (agent_id, article_url),
    CONSTRAINT fk_support_agent_consults_documentation_from FOREIGN KEY (agent_id) REFERENCES support_agent (agent_id),
    CONSTRAINT fk_support_agent_consults_documentation_to FOREIGN KEY (article_url) REFERENCES documentation (article_url)
);

-- ----------------------------------------------------------------------------
-- SupportAgent measuredAgainst SLA  (0..*); inverse measures (0..*)
-- Many-to-many, so it needs its own table.
-- ----------------------------------------------------------------------------
CREATE TABLE support_agent_measured_against_sla (
    agent_id VARCHAR(255) NOT NULL,  -- -> support_agent.agent_id
    level_code VARCHAR(32) NOT NULL,  -- -> sla.level_code
    tier_code VARCHAR(32) NOT NULL,  -- -> sla.tier_code
    CONSTRAINT pk_support_agent_measured_against_sla PRIMARY KEY (agent_id, level_code, tier_code),
    CONSTRAINT fk_support_agent_measured_against_sla_from FOREIGN KEY (agent_id) REFERENCES support_agent (agent_id),
    CONSTRAINT fk_support_agent_measured_against_sla_to FOREIGN KEY (level_code, tier_code) REFERENCES sla (level_code, tier_code)
);

