INSERT INTO severity_level (level_code, level_rank, level_name, definition) VALUES
    ('S1', 1, 'System Down', 'A production environment is unavailable to all users, or no user can sign in. Work has stopped. S1 handling assumes a customer contact is available to troubleshoot; if nobody is, the ticket drops to S2.'),
    ('S2', 2, 'Work Stoppage', 'Part of the product is unusable, or some users cannot complete a critical task. Others can keep working, but a fix or workaround is needed. A full outage of a non-production environment is also S2.'),
    ('S3', 3, 'Medium', 'A problem that needs investigation or scheduled work but is not stopping anyone. Resolution time is agreed with the customer.'),
    ('S4', 4, 'Low', 'How-to questions, planned maintenance and upgrades, enhancement requests and documentation issues. Usually closed on first contact.');

