-- ============================================================================
-- PART 2: ONTOLOGY CATALOG
-- The ontology as data: what Part 1 was built from, one row per fact.
-- ============================================================================


CREATE TABLE ont_domain_type (
    domain_type VARCHAR(32) NOT NULL,
    sort_order INTEGER NOT NULL,
    CONSTRAINT pk_ont_domain_type PRIMARY KEY (domain_type)
);

CREATE TABLE ont_class (
    class_id VARCHAR(64) NOT NULL,       -- e.g. sup:Account
    class_name VARCHAR(64) NOT NULL,
    domain_type VARCHAR(32) NOT NULL,
    status VARCHAR(16) NOT NULL,
    version VARCHAR(16) NOT NULL,
    definition TEXT NOT NULL,
    identity_rule TEXT NOT NULL,
    table_name VARCHAR(64) NOT NULL,     -- the Part 1 table
    primary_key_columns VARCHAR(255) NOT NULL,
    CONSTRAINT pk_ont_class PRIMARY KEY (class_id),
    CONSTRAINT uq_ont_class_name UNIQUE (class_name),
    CONSTRAINT fk_ont_class_domain_type FOREIGN KEY (domain_type) REFERENCES ont_domain_type (domain_type),
    CONSTRAINT ck_ont_class_status CHECK (status IN ('Canonical', 'Proposed', 'Deprecated'))
);

CREATE TABLE ont_attribute (
    class_id VARCHAR(64) NOT NULL,
    property_name VARCHAR(64) NOT NULL,  -- datatype property, e.g. accountName
    datatype VARCHAR(255) NOT NULL,      -- as declared, e.g. enum(Active, Lapsed, Churned)
    is_required BOOLEAN NOT NULL,
    notes TEXT,
    column_name VARCHAR(64) NOT NULL,
    sql_type VARCHAR(32) NOT NULL,
    CONSTRAINT pk_ont_attribute PRIMARY KEY (class_id, property_name),
    CONSTRAINT fk_ont_attribute_class FOREIGN KEY (class_id) REFERENCES ont_class (class_id)
);

CREATE TABLE ont_relationship (
    property_name VARCHAR(64) NOT NULL,  -- the verb, read Domain property Range
    domain_class_id VARCHAR(64) NOT NULL,
    range_class_id VARCHAR(64) NOT NULL,
    cardinality VARCHAR(8) NOT NULL,     -- range instances per domain instance
    inverse_name VARCHAR(64) NOT NULL,
    inverse_cardinality VARCHAR(8) NOT NULL,
    relationship_group VARCHAR(32) NOT NULL,
    notes TEXT,
    implemented_as VARCHAR(16) NOT NULL,
    physical_table VARCHAR(64) NOT NULL,
    physical_columns VARCHAR(255) NOT NULL,
    constraint_name VARCHAR(64) NOT NULL,
    CONSTRAINT pk_ont_relationship PRIMARY KEY (property_name),
    CONSTRAINT uq_ont_relationship_inverse UNIQUE (inverse_name),
    CONSTRAINT fk_ont_relationship_domain FOREIGN KEY (domain_class_id) REFERENCES ont_class (class_id),
    CONSTRAINT fk_ont_relationship_range FOREIGN KEY (range_class_id) REFERENCES ont_class (class_id),
    CONSTRAINT ck_ont_relationship_implemented_as CHECK (implemented_as IN ('FOREIGN_KEY', 'JUNCTION_TABLE'))
);

CREATE TABLE ont_constraint (
    constraint_id VARCHAR(8) NOT NULL,   -- C-nn, permanent
    status VARCHAR(8) NOT NULL,
    enforcement_level VARCHAR(8),        -- Hard, Soft, Advisory; NULL when retired
    category VARCHAR(64) NOT NULL,
    statement TEXT NOT NULL,
    catches TEXT,
    retired_reason TEXT,
    enforcement VARCHAR(16),             -- how this schema enforces it; NULL when retired
    physical_object VARCHAR(64),
    enforcement_note TEXT,
    CONSTRAINT pk_ont_constraint PRIMARY KEY (constraint_id),
    CONSTRAINT ck_ont_constraint_status CHECK (status IN ('Active', 'Retired')),
    CONSTRAINT ck_ont_constraint_level CHECK (enforcement_level IN ('Hard', 'Soft', 'Advisory')),
    CONSTRAINT ck_ont_constraint_enforcement
        CHECK (enforcement IN ('DECLARATIVE', 'STRUCTURAL', 'VIOLATION_VIEW', 'NOT_ENFORCED')),
    CONSTRAINT ck_ont_constraint_active
        CHECK ((status = 'Active' AND enforcement_level IS NOT NULL AND enforcement IS NOT NULL)
            OR (status = 'Retired' AND enforcement_level IS NULL AND enforcement IS NULL))
);

CREATE TABLE ont_disjointness (
    class_a_id VARCHAR(64) NOT NULL,
    class_b_id VARCHAR(64) NOT NULL,
    reason TEXT NOT NULL,
    CONSTRAINT pk_ont_disjointness PRIMARY KEY (class_a_id, class_b_id),
    CONSTRAINT fk_ont_disjointness_a FOREIGN KEY (class_a_id) REFERENCES ont_class (class_id),
    CONSTRAINT fk_ont_disjointness_b FOREIGN KEY (class_b_id) REFERENCES ont_class (class_id)
);

CREATE TABLE ont_individual (
    class_id VARCHAR(64) NOT NULL,
    individual_code VARCHAR(64) NOT NULL,
    label VARCHAR(255),
    sort_rank INTEGER,
    notes TEXT,
    CONSTRAINT pk_ont_individual PRIMARY KEY (class_id, individual_code),
    CONSTRAINT fk_ont_individual_class FOREIGN KEY (class_id) REFERENCES ont_class (class_id)
);

CREATE TABLE ont_alias (
    alias_id INTEGER NOT NULL,
    class_id VARCHAR(64) NOT NULL,
    individual_code VARCHAR(64),         -- NULL: alias of the class itself
    alias_term VARCHAR(255) NOT NULL,
    alias_context VARCHAR(255) NOT NULL, -- the system or team that uses it
    note TEXT,
    CONSTRAINT pk_ont_alias PRIMARY KEY (alias_id),
    CONSTRAINT fk_ont_alias_class FOREIGN KEY (class_id) REFERENCES ont_class (class_id),
    CONSTRAINT fk_ont_alias_individual FOREIGN KEY (class_id, individual_code)
        REFERENCES ont_individual (class_id, individual_code)
);

CREATE TABLE ont_equivalence (
    eq_id VARCHAR(8) NOT NULL,
    title VARCHAR(255) NOT NULL,
    kind VARCHAR(16) NOT NULL,
    canonical_ref VARCHAR(255),
    equivalent_labels TEXT,
    varies_by VARCHAR(64),
    anchor_property VARCHAR(128),
    status_note TEXT,
    CONSTRAINT pk_ont_equivalence PRIMARY KEY (eq_id),
    CONSTRAINT ck_ont_equivalence_kind CHECK (kind IN ('EQUIVALENCE', 'COLLISION'))
);

INSERT INTO ont_domain_type (domain_type, sort_order) VALUES
    ('Customer', 1),
    ('Product', 2),
    ('Support', 3),
    ('Engineering', 4),
    ('Knowledge', 5);

INSERT INTO ont_class (class_id, class_name, domain_type, status, version, definition, identity_rule, table_name, primary_key_columns) VALUES
    ('sup:Account', 'Account', 'Customer', 'Canonical', '0.1.0', 'A commercial customer organization that holds one or more licenses to our products and is entitled to receive support. The Account is the unit that entitlement, licensing, regional assignment and commercial ownership all hang off. An Account is an organization, never an individual person — the people at an account are modelled as sup:Contact.', 'The CRM account ID is authoritative. Where an organization exists as multiple account records across brand-specific CRM orgs, they are the same sup:Account only if they share a resolved parent organization ID. See OQ-03 — account de-duplication across brand orgs is unresolved.', 'account', 'account_id'),
    ('sup:Contact', 'Contact', 'Customer', 'Canonical', '0.2.1', 'An individual person at a customer account who is authorised to raise support tickets and use self-service tools. A Contact is a person in their capacity as a customer representative. Internal staff are modelled as sup:SupportAgent, sup:SalesRepresentative or sup:CustomerSuccessManager.', 'CRM contact ID is authoritative.', 'contact', 'contact_id'),
    ('sup:CustomerSuccessManager', 'CustomerSuccessManager', 'Customer', 'Canonical', '0.1.0', 'An internal individual assigned to accounts considered valuable, with responsibility for adoption, retention and relationship health. Unlike the sales representative, CSM assignment is conditional — most accounts do not have one.', 'The CRM user ID is authoritative.', 'customer_success_manager', 'csm_id'),
    ('sup:License', 'License', 'Customer', 'Canonical', '0.1.0', 'A grant of the right to use a specific product, held by a specific account, for a defined period and quantity. The license is what makes a support request legitimate: an account may only raise tickets about products it is licensed for.', 'Composite: accountId + productId + startDate. A renewal produces a new License instance rather than mutating the existing one, so that historical coverage questions stay answerable.', 'license', 'account_id, product_id, start_date'),
    ('sup:Partner', 'Partner', 'Customer', 'Proposed', '0.1.0', 'An Independent Software Vendor (ISV) or partner organization that represents one or more accounts. Partners can submit and manage support tickets on behalf of the customers they represent.', 'The CRM partner ID is authoritative.', 'partner', 'partner_id'),
    ('sup:Region', 'Region', 'Customer', 'Canonical', '0.1.0', 'A geographic territory used to distribute accounts and assign commercial and support coverage. Regions determine which sales representative owns an account and which support team''s working hours apply to its tickets.', 'Natural key: the region code (EMEA, NA, APAC, LATAM). Codes are stable and never reused.', 'region', 'region_code'),
    ('sup:SalesRepresentative', 'SalesRepresentative', 'Customer', 'Canonical', '0.1.0', 'An internal individual who commercially owns a set of accounts. Assignment is driven by region: an account''s sales representative is drawn from the representatives covering that account''s region.', 'The CRM user ID is authoritative.', 'sales_representative', 'rep_id'),
    ('sup:SupportEntitlement', 'SupportEntitlement', 'Customer', 'Canonical', '0.1.0', 'The tier of support service an account is entitled to receive. The tier governs response time targets, escalation rights and channel access. Entitlement is a property of the account, not of an individual ticket or license.', 'Natural key: the canonical tier code (STANDARD, PREMIUM). Entitlement is a controlled vocabulary, not a per-account record — the per-account fact is the hasEntitlement link, and its effective dates live on the link.', 'support_entitlement', 'tier_code'),
    ('sup:Product', 'Product', 'Product', 'Canonical', '0.2.0', 'A software product that customers license and raise support tickets about. The Product is what a license grants access to, what a ticket concerns, and what documentation describes. It is the join point between the commercial, support and knowledge parts of the model.', 'The licensing system product ID is authoritative. Version is not part of identity — a product and its versions are the same product. Version-specific facts would need sup:ProductVersion, which is not modelled (OQ-15).', 'product', 'product_id'),
    ('sup:CRM', 'CRM', 'Support', 'Canonical', '0.2.1', 'A customer relationship management system that records tickets. Each distinct CRM instance is a distinct instance of this class, because each carries its own ticket numbering, its own user records, and — critically — its own vocabulary.', 'Natural key: the system code (e.g. SF_EMEA, SF_AMER). Each org is a separate instance even when several orgs run on the same platform, because the ID spaces and the vocabulary do not carry across.', 'crm', 'system_code'),
    ('sup:Escalation', 'Escalation', 'Support', 'Canonical', '0.1.0', 'The act of a support agent referring a ticket to development because it has been identified as a defect or as a request for new functionality. The Escalation produces a Jira issue and is the only legitimate way a Jira ID becomes associated with a ticket.', 'Surrogate: generated UUID. There is no natural key — the same ticket can be escalated more than once, and the same Jira issue can receive escalations from many tickets.', 'escalation', 'escalation_id'),
    ('sup:SLA', 'SLA', 'Support', 'Proposed', '0.1.0', 'The Service Level Agreement that governs a ticket, dictating the target times for response and resolution. An SLA is determined by the severity of the ticket and the entitlement of the customer account. Support agents are measured against their ability to meet these SLA targets.', 'A composite of severityLevel + entitlementTier.', 'sla', 'level_code, tier_code'),
    ('sup:SeverityLevel', 'SeverityLevel', 'Support', 'Canonical', '0.1.0', 'The graded measure of a ticket''s business impact and urgency, used to set response expectations and routing. Every ticket has exactly one.', 'Natural key: the canonical level code S1–S4. All product-specific labels (P1, Critical, High, 1 - Urgent) resolve to one of these four.', 'severity_level', 'level_code'),
    ('sup:SupportAgent', 'SupportAgent', 'Support', 'Canonical', '0.1.0', 'An internal member of the support organization who is assigned tickets, resolves them using documentation, and escalates to development when a ticket is caused by a defect or requires new functionality.', 'The CRM user ID is authoritative. Agents appearing in more than one CRM are matched on corporate email.', 'support_agent', 'agent_id'),
    ('sup:Ticket', 'Ticket', 'Support', 'Canonical', '0.1.0', 'A single recorded request for support from a customer account, tracked from submission to resolution. One ticket represents one customer problem. It is owned by exactly one account, assigned to at most one agent at a time, carries exactly one severity, is governed by exactly one SLA, and may be escalated to development. It may be submitted by a Contact at the account or, where the customer buys through one, by a Partner acting on the account''s behalf.', 'The CRM ticket/case number is authoritative. Ticket numbers are unique within a CRM but not across CRMs — a fully qualified ticket identity is systemCode + ticketNumber. This is a real collision risk in reporting.', 'ticket', 'system_code, ticket_number'),
    ('sup:JiraIssue', 'JiraIssue', 'Engineering', 'Canonical', '0.1.0', 'A unit of engineering work tracked in Jira, created as the result of a support escalation, representing either a defect to fix or a capability to build. Its key is the identifier that gets associated back to the originating ticket.', 'The Jira issue key (e.g. PROJ-1234) is authoritative and globally unique.', 'jira_issue', 'issue_key'),
    ('sup:Documentation', 'Documentation', 'Knowledge', 'Canonical', '0.2.0', 'Published product documentation and knowledge base content that support agents consult to resolve tickets. One instance is one published unit — an article or page — identified by its URL.', 'The published URL is authoritative. Where content exists at several URLs (localised or mirrored), the canonical URL is the identity and the others are recorded as aliases.', 'documentation', 'article_url');

