INSERT INTO ont_relationship (property_name, domain_class_id, range_class_id, cardinality, inverse_name, inverse_cardinality, relationship_group, notes, implemented_as, physical_table, physical_columns, constraint_name) VALUES
    ('isLocatedIn', 'sup:Account', 'sup:Region', '1..1', 'isRegionOf', '0..*', 'Customer', 'Drives sales rep assignment via C-46', 'FOREIGN_KEY', 'account', 'region_code', 'fk_account_is_located_in'),
    ('hasEntitlement', 'sup:Account', 'sup:SupportEntitlement', '1..1', 'entitles', '0..*', 'Customer', 'Premium ≡ Platinum — resolve before comparing', 'FOREIGN_KEY', 'account', 'tier_code', 'fk_account_has_entitlement'),
    ('holdsLicense', 'sup:Account', 'sup:License', '0..*', 'isHeldBy', '1..1', 'Customer', NULL, 'FOREIGN_KEY', 'license', 'account_id', 'fk_license_is_held_by'),
    ('hasContact', 'sup:Account', 'sup:Contact', '0..*', 'worksFor', '1..1', 'Customer', 'Contact is Proposed', 'FOREIGN_KEY', 'contact', 'account_id', 'fk_contact_works_for'),
    ('hasSalesRep', 'sup:Account', 'sup:SalesRepresentative', '1..1', 'manages', '0..*', 'Customer', 'Rep must cover the account''s region — C-46', 'FOREIGN_KEY', 'account', 'rep_id', 'fk_account_has_sales_rep'),
    ('hasCSM', 'sup:Account', 'sup:CustomerSuccessManager', '0..1', 'supports', '0..*', 'Customer', 'Conditional — only if isStrategic — C-08', 'FOREIGN_KEY', 'account', 'csm_id', 'fk_account_has_csm'),
    ('isCoveredBy', 'sup:Region', 'sup:SalesRepresentative', '1..*', 'covers', '1..*', 'Customer', NULL, 'JUNCTION_TABLE', 'region_is_covered_by_sales_representative', 'region_code, rep_id', 'pk_region_is_covered_by_sales_representative'),
    ('binds', 'sup:SupportEntitlement', 'sup:License', '0..*', 'isBoundTo', '1..1', 'Customer', 'Entitlement also attaches to the license — OQ-42', 'FOREIGN_KEY', 'license', 'tier_code', 'fk_license_is_bound_to'),
    ('grantsAccessTo', 'sup:License', 'sup:Product', '1..1', 'isLicensedBy', '0..*', 'Customer', NULL, 'FOREIGN_KEY', 'license', 'product_id', 'fk_license_grants_access_to'),
    ('represents', 'sup:Partner', 'sup:Account', '0..*', 'isRepresentedBy', '0..*', 'Customer', NULL, 'JUNCTION_TABLE', 'partner_represents_account', 'partner_id, account_id', 'pk_partner_represents_account'),
    ('raisesOnBehalfOf', 'sup:Partner', 'sup:Ticket', '0..*', 'submittedByPartner', '0..1', 'Customer', NULL, 'FOREIGN_KEY', 'ticket', 'partner_id', 'fk_ticket_submitted_by_partner'),
    ('raises', 'sup:Account', 'sup:Ticket', '0..*', 'belongsTo', '1..1', 'Support', NULL, 'FOREIGN_KEY', 'ticket', 'account_id', 'fk_ticket_belongs_to'),
    ('submits', 'sup:Contact', 'sup:Ticket', '0..*', 'submittedBy', '0..1', 'Support', 'Contact must belong to the ticket''s account — C-16', 'FOREIGN_KEY', 'ticket', 'contact_id', 'fk_ticket_submitted_by'),
    ('concerns', 'sup:Ticket', 'sup:Product', '1..1', 'isSubjectOf', '0..*', 'Support', NULL, 'FOREIGN_KEY', 'ticket', 'product_id', 'fk_ticket_concerns'),
    ('assignedTo', 'sup:Ticket', 'sup:SupportAgent', '0..1', 'handles', '0..*', 'Support', 'At most one at a time — C-31', 'FOREIGN_KEY', 'ticket', 'agent_id', 'fk_ticket_assigned_to'),
    ('hasSeverity', 'sup:Ticket', 'sup:SeverityLevel', '1..1', 'appliesTo', '0..*', 'Support', 'Severity ≡ Priority — compare on levelRank only', 'FOREIGN_KEY', 'ticket', 'level_code', 'fk_ticket_has_severity'),
    ('escalatedAs', 'sup:Ticket', 'sup:Escalation', '0..*', 'originatesFrom', '1..1', 'Support', 'The only route to a Jira ID — C-05', 'FOREIGN_KEY', 'escalation', 'system_code, ticket_number', 'fk_escalation_originates_from'),
    ('resolvedUsing', 'sup:Ticket', 'sup:Documentation', '0..*', 'resolves', '0..*', 'Support', 'May be aspirational — OQ-30', 'JUNCTION_TABLE', 'ticket_resolved_using_documentation', 'system_code, ticket_number, article_url', 'pk_ticket_resolved_using_documentation'),
    ('recordedIn', 'sup:Ticket', 'sup:CRM', '1..1', 'records', '0..*', 'Support', 'Disambiguates ticket numbers across systems', 'FOREIGN_KEY', 'ticket', 'system_code', 'fk_ticket_recorded_in'),
    ('isGovernedBy', 'sup:Ticket', 'sup:SLA', '1..1', 'governs', '0..*', 'Support', 'SLA affects response/resolution times — C-56', 'FOREIGN_KEY', 'ticket', 'sla_level_code, sla_tier_code', 'fk_ticket_is_governed_by'),
    ('escalatedBy', 'sup:Escalation', 'sup:SupportAgent', '1..1', 'escalates', '0..*', 'Support', 'Only agents may escalate — C-29', 'FOREIGN_KEY', 'escalation', 'agent_id', 'fk_escalation_escalated_by'),
    ('specialisesIn', 'sup:SupportAgent', 'sup:Product', '0..*', 'isSupportedBy', '0..*', 'Support', 'Source may be informal — OQ-23', 'JUNCTION_TABLE', 'support_agent_specialises_in_product', 'agent_id, product_id', 'pk_support_agent_specialises_in_product'),
    ('consults', 'sup:SupportAgent', 'sup:Documentation', '0..*', 'isConsultedBy', '0..*', 'Support', NULL, 'JUNCTION_TABLE', 'support_agent_consults_documentation', 'agent_id, article_url', 'pk_support_agent_consults_documentation'),
    ('measuredAgainst', 'sup:SupportAgent', 'sup:SLA', '0..*', 'measures', '0..*', 'Support', NULL, 'JUNCTION_TABLE', 'support_agent_measured_against_sla', 'agent_id, level_code, tier_code', 'pk_support_agent_measured_against_sla'),
    ('producedIssue', 'sup:Escalation', 'sup:JiraIssue', '1..1', 'raisedBy', '1..*', 'Engineering', 'Inverse is 1..* — many escalations, one issue', 'FOREIGN_KEY', 'escalation', 'issue_key', 'fk_escalation_produced_issue'),
    ('describes', 'sup:Documentation', 'sup:Product', '1..1', 'isDescribedBy', '0..*', 'Knowledge', 'Soft cardinality — C-55', 'FOREIGN_KEY', 'documentation', 'product_id', 'fk_documentation_describes');

INSERT INTO ont_constraint (constraint_id, status, enforcement_level, category, statement, catches, retired_reason, enforcement, physical_object, enforcement_note) VALUES
    ('C-01', 'Active', 'Hard', 'Cardinality constraints', 'Every Account is located in exactly one Region.', NULL, NULL, 'STRUCTURAL', NULL, 'account.region_code is a NOT NULL foreign key.'),
    ('C-02', 'Active', 'Hard', 'Cardinality constraints', 'Every Account has exactly one SupportEntitlement at a given point in time.', NULL, NULL, 'STRUCTURAL', NULL, 'account.tier_code is a NOT NULL foreign key. Only the current tier is stored; effective dates on the link are not modelled.'),
    ('C-04', 'Active', 'Hard', 'Cardinality constraints', 'Every Ticket has exactly one Account, exactly one SeverityLevel, and exactly one Product.', NULL, NULL, 'STRUCTURAL', NULL, 'ticket.account_id, level_code and product_id are NOT NULL foreign keys.'),
    ('C-07', 'Active', 'Hard', 'Cardinality constraints', 'Every Account has exactly one SalesRepresentative.', NULL, NULL, 'STRUCTURAL', NULL, 'account.rep_id is a NOT NULL foreign key.'),
    ('C-10', 'Active', 'Hard', 'Cardinality constraints', 'Every Region is covered by at least one SalesRepresentative.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c10', NULL),
    ('C-15', 'Active', 'Hard', 'Cardinality constraints', 'Every Contact belongs to exactly one Account.', NULL, NULL, 'STRUCTURAL', NULL, 'contact.account_id is a NOT NULL foreign key.'),
    ('C-27', 'Active', 'Hard', 'Cardinality constraints', 'Every Escalation produces exactly one JiraIssue.', NULL, NULL, 'STRUCTURAL', NULL, 'escalation.issue_key is a NOT NULL foreign key.'),
    ('C-31', 'Active', 'Hard', 'Cardinality constraints', 'A Ticket is assigned to at most one SupportAgent at a time.', NULL, NULL, 'STRUCTURAL', NULL, 'ticket.agent_id is one column; assignment history is not modelled.'),
    ('C-33', 'Active', 'Hard', 'Cardinality constraints', 'Every JiraIssue in scope traces back to at least one Escalation. Engineering-initiated issues are out of scope and must not be loaded.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c33', NULL),
    ('C-47', 'Active', 'Hard', 'Cardinality constraints', 'An Account has at most one CustomerSuccessManager.', NULL, NULL, 'STRUCTURAL', NULL, 'account.csm_id is a single column.'),
    ('C-48', 'Active', 'Hard', 'Cardinality constraints', 'Every Ticket is recorded in exactly one CRM.', NULL, NULL, 'STRUCTURAL', NULL, 'ticket.system_code is NOT NULL and part of the primary key.'),
    ('C-53', 'Active', 'Hard', 'Cardinality constraints', 'Every License is bound to exactly one SupportEntitlement.', NULL, NULL, 'STRUCTURAL', NULL, 'license.tier_code is a NOT NULL foreign key.'),
    ('C-55', 'Active', 'Soft', 'Cardinality constraints', 'Every Documentation instance describes exactly one Product. Cross-product overview pages legitimately exist, so this flags rather than rejects.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c55', NULL),
    ('C-56', 'Active', 'Hard', 'Cardinality constraints', 'Every Ticket has exactly one SLA, determined by its SeverityLevel and Account''s SupportEntitlement.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c56', NULL),
    ('C-08', 'Active', 'Hard', 'Conditional constraints', 'An Account may have a CSM only if isStrategic = true. Note the direction: strategic permits a CSM, it does not require one. A strategic account with no CSM is valid (awaiting assignment); a non-strategic account with a CSM is not.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c08', NULL),
    ('C-05', 'Active', 'Hard', 'Conditional constraints', 'A Ticket may carry a Jira reference only through an Escalation. A Jira ID on a ticket with no escalation record is invalid — the link exists but the reason, the author and the date have been lost.', NULL, NULL, 'STRUCTURAL', NULL, 'ticket has no Jira column. The only path is escalation.issue_key.'),
    ('C-06', 'Active', 'Hard', 'Conditional constraints', 'A Ticket with status = Escalated has at least one open Escalation.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c06', NULL),
    ('C-12', 'Active', 'Hard', 'Conditional constraints', 'grantsEscalationRight is true only for the PREMIUM tier.', NULL, NULL, 'DECLARATIVE', 'ck_support_entitlement_c12', 'CHECK (grants_escalation_right = FALSE OR tier_code = ''PREMIUM'')'),
    ('C-17', 'Active', 'Hard', 'Conditional constraints', 'Only a Contact with isSupportAuthorised = true may submit a Ticket.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c17', NULL),
    ('C-22', 'Active', 'Hard', 'Conditional constraints', 'A Product with lifecycleStatus = EndOfLife must have an endOfLifeDate.', NULL, NULL, 'DECLARATIVE', 'ck_product_c22', 'CHECK (lifecycle_status <> ''EndOfLife'' OR end_of_life_date IS NOT NULL)'),
    ('C-29', 'Active', 'Hard', 'Conditional constraints', 'Only a SupportAgent may create an Escalation. Not a CSM, not a sales rep.', NULL, NULL, 'STRUCTURAL', NULL, 'escalation.agent_id references support_agent only.'),
    ('C-46', 'Active', 'Soft', 'Conditional constraints', 'An Account''s SalesRepresentative must cover the Account''s Region. This is "assigned depending on the region" made checkable — and it is the constraint most likely to fail after a territory reshuffle.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c46', NULL),
    ('C-50', 'Active', 'Hard', 'Conditional constraints', 'Every CRM declares ticketTermUsed. A system whose vocabulary is unknown cannot have its records safely translated.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c50', NULL),
    ('C-51', 'Active', 'Hard', 'Conditional constraints', 'Every Product declares usesPlatinumNaming and severityTermUsed. A product whose support vocabulary is unknown cannot have its tickets safely compared against another product''s.', NULL, NULL, 'DECLARATIVE', NULL, 'product.uses_platinum_naming and severity_term_used are NOT NULL.'),
    ('C-11', 'Active', 'Hard', 'Closed vocabulary constraints', 'The SupportEntitlement tier set is closed at STANDARD and PREMIUM. A value that does not resolve to one of these after alias resolution is a data error or an alias gap, never a new tier.', NULL, NULL, 'DECLARATIVE', NULL, 'CHECK on support_entitlement.tier_code, seeded with both tiers.'),
    ('C-25', 'Active', 'Hard', 'Closed vocabulary constraints', 'The SeverityLevel set is closed at S1–S4. A product-specific value that does not resolve is an alias gap to record in 03-Vocabulary-and-Equivalence.md, not a fifth level.', NULL, NULL, 'DECLARATIVE', NULL, 'CHECK on severity_level.level_code, seeded with S1-S4.'),
    ('C-26', 'Active', 'Hard', 'Closed vocabulary constraints', 'Severity comparisons, filters and sorts operate on levelRank only — never on the customer-facing label. "High" > "Critical" is true as a string comparison and false as a fact.', NULL, NULL, 'NOT_ENFORCED', NULL, 'Query rule: compare severity_level.level_rank, never labels.'),
    ('C-34', 'Active', 'Hard', 'Closed vocabulary constraints', 'JiraIssue.isResolved is derived from a per-project status mapping, not from the raw status string. Jira projects use different workflows and "Done" is not universal.', NULL, NULL, 'NOT_ENFORCED', NULL, 'isResolved is derived upstream from a per-project status mapping.'),
    ('C-52', 'Active', 'Hard', 'Disjointness', 'SupportAgent, SalesRepresentative and CustomerSuccessManager are pairwise disjoint. These are three distinct jobs in the support and commercial organization.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c52', NULL),
    ('C-13', 'Active', 'Hard', 'Referential and temporal integrity', 'License.endDate, when present, is later than startDate.', NULL, NULL, 'DECLARATIVE', 'ck_license_c13', 'CHECK (end_date IS NULL OR end_date > start_date)'),
    ('C-16', 'Active', 'Soft', 'Referential and temporal integrity', 'A Ticket''s submitting Contact must belong to the Ticket''s Account.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c16', NULL),
    ('C-24', 'Active', 'Hard', 'Referential and temporal integrity', 'Ticket.resolvedAt is required when status is Resolved or Closed, and must not precede openedAt.', NULL, NULL, 'DECLARATIVE', 'ck_ticket_c24', 'CHECK ((status NOT IN (''Resolved'', ''Closed'') OR resolved_at IS NOT NULL) AND (resolved_at IS NULL OR resolved_at >= opened_at))'),
    ('C-49', 'Active', 'Hard', 'Referential and temporal integrity', 'A fact from a CRM with isAuthoritative = false must not override a fact from an authoritative system for the same property. Mirrors lag.', NULL, NULL, 'NOT_ENFORCED', NULL, 'Needs fact-level provenance, which this schema does not store.'),
    ('C-57', 'Active', 'Hard', 'Referential and temporal integrity', 'A Ticket raised by a Partner must belong to an Account that the Partner represents.', NULL, NULL, 'VIOLATION_VIEW', 'v_violation_c57', NULL),
    ('C-09', 'Active', 'Soft', 'Operational rules (Soft and Advisory)', 'An Account with accountStatus = Active holds at least one active License.', 'Accounts marked active after everything lapsed.', NULL, 'VIOLATION_VIEW', 'v_violation_c09', NULL),
    ('C-14', 'Active', 'Soft', 'Operational rules (Soft and Advisory)', 'A Ticket''s product should be covered by an active License at the time it was opened.', 'Out-of-maintenance support requests. Legitimate and common — flag, never reject.', NULL, 'VIOLATION_VIEW', 'v_violation_c14', NULL),
    ('C-23', 'Active', 'Advisory', 'Operational rules (Soft and Advisory)', 'Documentation describing an EndOfLife product is a retirement candidate.', 'Feeds the KB evaluation process.', NULL, 'VIOLATION_VIEW', 'v_violation_c23', NULL),
    ('C-28', 'Active', 'Advisory', 'Operational rules (Soft and Advisory)', 'An Escalation of type Bug should have reproductionSteps.', 'Escalations development will bounce back.', NULL, 'VIOLATION_VIEW', 'v_violation_c28', NULL),
    ('C-32', 'Active', 'Soft', 'Operational rules (Soft and Advisory)', 'An inactive SupportAgent must not hold open tickets.', 'Tickets orphaned when someone leaves. Real, common, and invisible until a customer chases.', NULL, 'VIOLATION_VIEW', 'v_violation_c32', NULL),
    ('C-35', 'Active', 'Soft', 'Operational rules (Soft and Advisory)', 'A resolved JiraIssue with unresolved originating Tickets.', 'The fix shipped and nobody told the customer. Probably the highest-value check here.', NULL, 'VIOLATION_VIEW', 'v_violation_c35', NULL),
    ('C-40', 'Active', 'Advisory', 'Operational rules (Soft and Advisory)', 'Documentation not reviewed in 24 months is a review candidate.', 'Stale content agents are still trusting.', NULL, 'NOT_ENFORCED', NULL, 'Needs date arithmetic, which is not portable. PostgreSQL: WHERE last_reviewed_at < CURRENT_DATE - INTERVAL ''24 months''.'),
    ('C-54', 'Active', 'Soft', 'Operational rules (Soft and Advisory)', 'A License''s SupportEntitlement should match its Account''s SupportEntitlement.', 'The model''s own open question, made checkable. If accounts routinely hold licenses at different tiers, entitlement belongs on the license and C-02 is wrong. Flagging rather than rejecting means the first real violation tells us which model is right, instead of the data being quietly reshaped to fit our guess. See OQ-42.', NULL, 'VIOLATION_VIEW', 'v_violation_c54', NULL),
    ('C-03', 'Retired', NULL, 'Retired constraints', 'hasSubRegion transitive and acyclic', NULL, 'Sub-regions removed — regions are flat.', NULL, NULL, NULL),
    ('C-18', 'Retired', NULL, 'Retired constraints', 'Every Brand declares its three vocabulary properties', NULL, 'Brand removed; replaced by C-51 on Product and C-50 on CRM.', NULL, NULL, NULL),
    ('C-19', 'Retired', NULL, 'Retired constraints', 'Every ProductLine belongs to one Brand', NULL, 'Both classes removed.', NULL, NULL, NULL),
    ('C-20', 'Retired', NULL, 'Retired constraints', 'ProductLine naming agrees with its Brand', NULL, 'Both classes removed.', NULL, NULL, NULL),
    ('C-21', 'Retired', NULL, 'Retired constraints', 'Every Product belongs to one ProductLine', NULL, 'ProductLine removed; Product is now flat.', NULL, NULL, NULL),
    ('C-30', 'Retired', NULL, 'Retired constraints', 'Role instances disjoint, persons not', NULL, 'Person removed; replaced by C-52.', NULL, NULL, NULL),
    ('C-36', 'Retired', NULL, 'Retired constraints', 'Every JiraIssue owned by one DevelopmentTeam', NULL, 'DevelopmentTeam out of scope.', NULL, NULL, NULL),
    ('C-37', 'Retired', NULL, 'Retired constraints', 'Every Product has an owning DevelopmentTeam', NULL, 'DevelopmentTeam out of scope.', NULL, NULL, NULL),
    ('C-38', 'Retired', NULL, 'Retired constraints', 'AI-indexed articles must be public', NULL, 'AIAssistant deferred.', NULL, NULL, NULL),
    ('C-39', 'Retired', NULL, 'Retired constraints', 'Articles with no inbound link are orphans', NULL, 'Article link graph left to the KB evaluation tooling.', NULL, NULL, NULL),
    ('C-41', 'Retired', NULL, 'Retired constraints', 'No article may be its own ancestor', NULL, 'Article link graph removed.', NULL, NULL, NULL),
    ('C-42', 'Retired', NULL, 'Retired constraints', 'Every AIAssistant is grounded in ≥1 article', NULL, 'AIAssistant deferred.', NULL, NULL, NULL),
    ('C-43', 'Retired', NULL, 'Retired constraints', 'Article changes trigger re-indexing', NULL, 'AIAssistant deferred.', NULL, NULL, NULL),
    ('C-44', 'Retired', NULL, 'Retired constraints', 'Unemployed Person holds no active roles', NULL, 'Person removed.', NULL, NULL, NULL),
    ('C-45', 'Retired', NULL, 'Retired constraints', 'Every role instance held by exactly one Person', NULL, 'Person removed.', NULL, NULL, NULL);

INSERT INTO ont_disjointness (class_a_id, class_b_id, reason) VALUES
    ('sup:Ticket', 'sup:JiraIssue', 'The most important one. Natural language collapses them constantly. A ticket is the customer''s request; a Jira issue is internal work. They have different lifecycles and are routinely in different states — "it''s fixed" is true of one and false of the other.'),
    ('sup:Account', 'sup:Contact', 'An account is an organization. Even a one-person customer is an organization holding a license.'),
    ('sup:Contact', 'sup:SupportAgent', 'A Contact acts for the customer; an agent, rep or CSM acts for us.'),
    ('sup:Contact', 'sup:SalesRepresentative', 'A Contact acts for the customer; an agent, rep or CSM acts for us.'),
    ('sup:Contact', 'sup:CustomerSuccessManager', 'A Contact acts for the customer; an agent, rep or CSM acts for us.'),
    ('sup:License', 'sup:SupportEntitlement', 'A license grants product usage; an entitlement grants service level. Salesforce''s use of "Entitlement" for the tier and "Asset" for the license makes this collision live.'),
    ('sup:Escalation', 'sup:Ticket', 'The escalation is the link, not either end of it.'),
    ('sup:Escalation', 'sup:JiraIssue', 'The escalation is the link, not either end of it.'),
    ('sup:CRM', 'sup:Account', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:Contact', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:CustomerSuccessManager', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:Documentation', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:Escalation', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:JiraIssue', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:License', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:Partner', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:Product', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:Region', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:SLA', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:SalesRepresentative', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:SeverityLevel', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:SupportAgent', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:SupportEntitlement', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:CRM', 'sup:Ticket', 'A CRM holds facts about the organization; it is not part of it.'),
    ('sup:Partner', 'sup:Account', 'A partner represents an account but is a separate organization.');

INSERT INTO ont_individual (class_id, individual_code, label, sort_rank, notes) VALUES
    ('sup:Region', 'EMEA', 'Europe, Middle East and Africa', NULL, NULL),
    ('sup:Region', 'NA', 'North America', NULL, NULL),
    ('sup:Region', 'APAC', 'Asia Pacific', NULL, NULL),
    ('sup:Region', 'LATAM', 'Latin America', NULL, NULL),
    ('sup:SeverityLevel', 'S1', 'System Down', 1, 'A production environment is unavailable to all users, or no user can sign in. Work has stopped. S1 handling assumes a customer contact is available to troubleshoot; if nobody is, the ticket drops to S2.'),
    ('sup:SeverityLevel', 'S2', 'Work Stoppage', 2, 'Part of the product is unusable, or some users cannot complete a critical task. Others can keep working, but a fix or workaround is needed. A full outage of a non-production environment is also S2.'),
    ('sup:SeverityLevel', 'S3', 'Medium', 3, 'A problem that needs investigation or scheduled work but is not stopping anyone. Resolution time is agreed with the customer.'),
    ('sup:SeverityLevel', 'S4', 'Low', 4, 'How-to questions, planned maintenance and upgrades, enhancement requests and documentation issues. Usually closed on first contact.'),
    ('sup:SupportEntitlement', 'STANDARD', 'Standard', 1, '"Basic", "Included Support" — usage unverified, see OQ-07'),
    ('sup:SupportEntitlement', 'PREMIUM', 'Premium', 2, '"Platinum Support" for the products that use that naming — see sup:Product.usesPlatinumNaming. Same tier, different label.'),
    ('sup:CRM', 'SF', 'Salesforce', NULL, 'Example: Case is the platform''s own object name'),
    ('sup:CRM', 'ZD', 'Zendesk', NULL, 'Example: Ticket is the platform''s own object name'),
    ('sup:Product', 'ExampleAnalytics', 'ExampleAnalytics', NULL, 'Working set: family-level name (OQ-14)'),
    ('sup:Product', 'ExampleDataWarehouse', 'ExampleDataWarehouse', NULL, 'Working set: family-level name (OQ-14)'),
    ('sup:Product', 'ExampleDesigner', 'ExampleDesigner', NULL, 'Working set: family-level name (OQ-14)');

