    ('DEVICE_SERIAL', 'PSEUDONYMIZE', 0.5, 90, TRUE, NULL, NULL, 'Hardware serial in a ticket body. sup:License covers licence keys (alias ''Serial''), not physical devices. No asset/device class exists.', 'Customer-linkable via RMA. No ontology class — see ontology.py.'),
    ('IBAN_CODE', 'REDACT', 0.4, 100, TRUE, NULL, NULL, 'Out of ontology scope by design.', 'Never recoverable.'),
    ('IP_ADDRESS', 'PSEUDONYMIZE', 0.5, 80, TRUE, NULL, NULL, 'No infrastructure or host class in scope.', 'Often the customer''s own host; keep shape for triage.'),
    ('JIRA_ISSUE_KEY', 'KEEP', 0.5, 85, TRUE, 'sup:JiraIssue', 'issueKey', NULL, 'sup:JiraIssue.issueKey. Engineering-internal, not customer data.'),
