    ('LOCATION', 'PSEUDONYMIZE', 0.6, 70, FALSE, NULL, NULL, 'A site or postal address. Distinct from sup:Region, which is a four-value controlled vocabulary, not a place a customer sits.', 'Site or postal address. Distinct from sup:Region.'),
    ('MAC_ADDRESS', 'PSEUDONYMIZE', 0.5, 100, TRUE, NULL, NULL, 'No infrastructure or host class in scope.', 'Hardware identifier.'),
    ('MEDICAL_LICENSE', 'REDACT', 0.4, 20, FALSE, NULL, NULL, 'Out of ontology scope by design.', 'Never recoverable.'),
    ('NRP', 'REDACT', 0.6, 20, FALSE, NULL, NULL, 'Special-category data. No ontology class, by design.', 'Nationality/religion/politics. Never belongs in a KB article.'),
