    ('PARTNER', 'PSEUDONYMIZE', 0.5, 95, FALSE, 'sup:Partner', NULL, NULL, 'ISV/partner org. Disjoint from Account — never merge the two.'),
    ('PERSON_UNRESOLVED', 'PSEUDONYMIZE', 0.6, 70, FALSE, NULL, NULL, 'A person name that resolved to no role deny-list. The ontology deliberately has no generic person layer (OQ-47), so there is no class to assign. Masked all the same; the role is left unclaimed rather than guessed.', 'Person with no resolved role. Masked, not classified.'),
    ('PHONE_NUMBER', 'PSEUDONYMIZE', 0.35, 80, TRUE, NULL, NULL, 'sup:Contact models emailAddress but no telephone property, though phone numbers appear throughout real ticket text.', 'Presidio scores these low; tuned against corpus.'),
