-- ============================================================================
-- PART 4: VIEWS
-- One view per cross-row constraint. Each returns the records that break it,
-- and v_constraint_violations gathers them all. On a fresh load, expect C-10
-- for all four regions (no sales reps loaded yet), plus C-50 for any CRM
-- whose ticket term is still unconfirmed.
-- ============================================================================

-- C-06 (Hard): A Ticket with status = Escalated has at least one open Escalation.
CREATE VIEW v_violation_c06 AS
SELECT 'ticket' AS table_name, t.system_code || ':' || t.ticket_number AS record_key,
       'status is Escalated but no Escalation exists' AS detail
FROM ticket t
WHERE t.status = 'Escalated'
  AND NOT EXISTS (SELECT 1 FROM escalation e
                  WHERE e.system_code = t.system_code AND e.ticket_number = t.ticket_number);

-- C-08 (Hard): An Account may have a CSM only if isStrategic = true. Note the
--   direction: strategic permits a CSM, it does not require one. A strategic
--   account with no CSM is valid (awaiting assignment); a non-strategic
--   account with a CSM is not.
CREATE VIEW v_violation_c08 AS
SELECT 'account' AS table_name, a.account_id AS record_key,
       'has a CSM but isStrategic is not true' AS detail
FROM account a
WHERE a.csm_id IS NOT NULL AND (a.is_strategic IS NULL OR a.is_strategic = FALSE);

-- C-09 (Soft): An Account with accountStatus = Active holds at least one active
--   License.
CREATE VIEW v_violation_c09 AS
SELECT 'account' AS table_name, a.account_id AS record_key,
       'Active account holds no active License' AS detail
FROM account a
WHERE a.account_status = 'Active'
  AND NOT EXISTS (SELECT 1 FROM license l WHERE l.account_id = a.account_id AND l.is_active = TRUE);

-- C-10 (Hard): Every Region is covered by at least one SalesRepresentative.
CREATE VIEW v_violation_c10 AS
SELECT 'region' AS table_name, r.region_code AS record_key,
       'no SalesRepresentative covers this Region' AS detail
FROM region r
WHERE NOT EXISTS (SELECT 1 FROM region_is_covered_by_sales_representative c
                  WHERE c.region_code = r.region_code);

-- C-14 (Soft): A Ticket's product should be covered by an active License at the time it
--   was opened.
CREATE VIEW v_violation_c14 AS
SELECT 'ticket' AS table_name, t.system_code || ':' || t.ticket_number AS record_key,
       'no active License covered the product when the ticket opened' AS detail
FROM ticket t
WHERE NOT EXISTS (SELECT 1 FROM license l
                  WHERE l.account_id = t.account_id AND l.product_id = t.product_id
                    AND l.start_date <= t.opened_at
                    AND (l.end_date IS NULL OR l.end_date >= t.opened_at));

-- C-16 (Soft): A Ticket's submitting Contact must belong to the Ticket's Account.
CREATE VIEW v_violation_c16 AS
SELECT 'ticket' AS table_name, t.system_code || ':' || t.ticket_number AS record_key,
       'submitting Contact works for a different Account' AS detail
FROM ticket t
JOIN contact c ON c.contact_id = t.contact_id
WHERE c.account_id <> t.account_id;

-- C-17 (Hard): Only a Contact with isSupportAuthorised = true may submit a Ticket.
CREATE VIEW v_violation_c17 AS
SELECT 'ticket' AS table_name, t.system_code || ':' || t.ticket_number AS record_key,
       'submitted by a Contact who is not support-authorised' AS detail
FROM ticket t
JOIN contact c ON c.contact_id = t.contact_id
WHERE c.is_support_authorised = FALSE;

-- C-23 (Advisory): Documentation describing an EndOfLife product is a retirement candidate.
CREATE VIEW v_violation_c23 AS
SELECT 'documentation' AS table_name, d.article_url AS record_key,
       'describes an EndOfLife product: retirement candidate' AS detail
FROM documentation d
JOIN product p ON p.product_id = d.product_id
WHERE p.lifecycle_status = 'EndOfLife';

-- C-28 (Advisory): An Escalation of type Bug should have reproductionSteps.
CREATE VIEW v_violation_c28 AS
SELECT 'escalation' AS table_name, e.escalation_id AS record_key,
       'Bug escalation without reproductionSteps' AS detail
FROM escalation e
WHERE e.escalation_type = 'Bug'
  AND (e.reproduction_steps IS NULL OR TRIM(e.reproduction_steps) = '');

-- C-32 (Soft): An inactive SupportAgent must not hold open tickets.
CREATE VIEW v_violation_c32 AS
SELECT 'ticket' AS table_name, t.system_code || ':' || t.ticket_number AS record_key,
       'open ticket assigned to an inactive SupportAgent' AS detail
FROM ticket t
JOIN support_agent s ON s.agent_id = t.agent_id
WHERE s.is_active = FALSE AND t.status NOT IN ('Resolved', 'Closed');

-- C-33 (Hard): Every JiraIssue in scope traces back to at least one Escalation.
--   Engineering-initiated issues are out of scope and must not be loaded.
CREATE VIEW v_violation_c33 AS
SELECT 'jira_issue' AS table_name, j.issue_key AS record_key,
       'no Escalation traces to this issue' AS detail
FROM jira_issue j
WHERE NOT EXISTS (SELECT 1 FROM escalation e WHERE e.issue_key = j.issue_key);

-- C-35 (Soft): A resolved JiraIssue with unresolved originating Tickets.
CREATE VIEW v_violation_c35 AS
SELECT 'jira_issue' AS table_name, j.issue_key AS record_key,
       'resolved, but originating ticket ' || t.system_code || ':' || t.ticket_number
       || ' is still open' AS detail
FROM jira_issue j
JOIN escalation e ON e.issue_key = j.issue_key
JOIN ticket t ON t.system_code = e.system_code AND t.ticket_number = e.ticket_number
WHERE j.is_resolved = TRUE AND t.status NOT IN ('Resolved', 'Closed');

-- C-46 (Soft): An Account's SalesRepresentative must cover the Account's Region. This
--   is "assigned depending on the region" made checkable — and it is the
--   constraint most likely to fail after a territory reshuffle.
CREATE VIEW v_violation_c46 AS
SELECT 'account' AS table_name, a.account_id AS record_key,
       'SalesRepresentative does not cover the Account''s Region' AS detail
FROM account a
WHERE NOT EXISTS (SELECT 1 FROM region_is_covered_by_sales_representative c
                  WHERE c.region_code = a.region_code AND c.rep_id = a.rep_id);

-- C-50 (Hard): Every CRM declares ticketTermUsed. A system whose vocabulary is unknown
--   cannot have its records safely translated.
CREATE VIEW v_violation_c50 AS
SELECT 'crm' AS table_name, c.system_code AS record_key,
       'ticketTermUsed is not declared' AS detail
FROM crm c
WHERE c.ticket_term_used IS NULL;

-- C-52 (Hard): SupportAgent, SalesRepresentative and CustomerSuccessManager are
--   pairwise disjoint. These are three distinct jobs in the support and
--   commercial organization.
CREATE VIEW v_violation_c52 AS
SELECT 'support_agent' AS table_name, s.agent_id AS record_key,
       'also a SalesRepresentative' AS detail
FROM support_agent s JOIN sales_representative r ON r.rep_id = s.agent_id
UNION ALL
SELECT 'support_agent', s.agent_id, 'also a CustomerSuccessManager'
FROM support_agent s JOIN customer_success_manager m ON m.csm_id = s.agent_id
UNION ALL
SELECT 'sales_representative', r.rep_id, 'also a CustomerSuccessManager'
FROM sales_representative r JOIN customer_success_manager m ON m.csm_id = r.rep_id;

-- C-54 (Soft): A License's SupportEntitlement should match its Account's
--   SupportEntitlement.
CREATE VIEW v_violation_c54 AS
SELECT 'license' AS table_name,
       l.account_id || ':' || l.product_id || ':' || CAST(l.start_date AS VARCHAR(10)) AS record_key,
       'License tier differs from its Account''s tier' AS detail
FROM license l
JOIN account a ON a.account_id = l.account_id
WHERE l.tier_code <> a.tier_code;

-- C-55 (Soft): Every Documentation instance describes exactly one Product. Cross-
--   product overview pages legitimately exist, so this flags rather than
--   rejects.
CREATE VIEW v_violation_c55 AS
SELECT 'documentation' AS table_name, d.article_url AS record_key,
       'describes no Product' AS detail
FROM documentation d
WHERE d.product_id IS NULL;

-- C-56 (Hard): Every Ticket has exactly one SLA, determined by its SeverityLevel and
--   Account's SupportEntitlement.
CREATE VIEW v_violation_c56 AS
SELECT 'ticket' AS table_name, t.system_code || ':' || t.ticket_number AS record_key,
       'SLA does not match the ticket severity and account entitlement' AS detail
FROM ticket t
JOIN account a ON a.account_id = t.account_id
WHERE t.sla_level_code <> t.level_code OR t.sla_tier_code <> a.tier_code;

-- C-57 (Hard): A Ticket raised by a Partner must belong to an Account that the Partner
--   represents.
CREATE VIEW v_violation_c57 AS
SELECT 'ticket' AS table_name, t.system_code || ':' || t.ticket_number AS record_key,
       'raised by a Partner that does not represent the Account' AS detail
FROM ticket t
WHERE t.partner_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM partner_represents_account p
                  WHERE p.partner_id = t.partner_id AND p.account_id = t.account_id);

CREATE VIEW v_constraint_violations AS
SELECT v.constraint_id, c.enforcement_level, v.table_name, v.record_key, v.detail
FROM (
SELECT 'C-06' AS constraint_id, table_name, record_key, detail FROM v_violation_c06
UNION ALL
SELECT 'C-08' AS constraint_id, table_name, record_key, detail FROM v_violation_c08
UNION ALL
SELECT 'C-09' AS constraint_id, table_name, record_key, detail FROM v_violation_c09
UNION ALL
SELECT 'C-10' AS constraint_id, table_name, record_key, detail FROM v_violation_c10
UNION ALL
SELECT 'C-14' AS constraint_id, table_name, record_key, detail FROM v_violation_c14
UNION ALL
SELECT 'C-16' AS constraint_id, table_name, record_key, detail FROM v_violation_c16
UNION ALL
SELECT 'C-17' AS constraint_id, table_name, record_key, detail FROM v_violation_c17
UNION ALL
SELECT 'C-23' AS constraint_id, table_name, record_key, detail FROM v_violation_c23
UNION ALL
SELECT 'C-28' AS constraint_id, table_name, record_key, detail FROM v_violation_c28
UNION ALL
SELECT 'C-32' AS constraint_id, table_name, record_key, detail FROM v_violation_c32
UNION ALL
SELECT 'C-33' AS constraint_id, table_name, record_key, detail FROM v_violation_c33
UNION ALL
SELECT 'C-35' AS constraint_id, table_name, record_key, detail FROM v_violation_c35
UNION ALL
SELECT 'C-46' AS constraint_id, table_name, record_key, detail FROM v_violation_c46
UNION ALL
SELECT 'C-50' AS constraint_id, table_name, record_key, detail FROM v_violation_c50
UNION ALL
SELECT 'C-52' AS constraint_id, table_name, record_key, detail FROM v_violation_c52
UNION ALL
SELECT 'C-54' AS constraint_id, table_name, record_key, detail FROM v_violation_c54
UNION ALL
SELECT 'C-55' AS constraint_id, table_name, record_key, detail FROM v_violation_c55
UNION ALL
SELECT 'C-56' AS constraint_id, table_name, record_key, detail FROM v_violation_c56
UNION ALL
SELECT 'C-57' AS constraint_id, table_name, record_key, detail FROM v_violation_c57
) v
JOIN ont_constraint c ON c.constraint_id = v.constraint_id;

-- Required values the ontology has not confirmed yet, left NULL rather than guessed.
CREATE VIEW v_seed_gaps AS
SELECT 'crm' AS table_name, system_code AS record_key, 'ticketTermUsed' AS property_name, 'OQ-50' AS open_question, 'Confirmed for Salesforce only.' AS reason FROM crm WHERE ticket_term_used IS NULL
UNION ALL
SELECT 'crm' AS table_name, system_code AS record_key, 'isAuthoritative' AS property_name, 'OQ-50' AS open_question, 'Unconfirmed for Zendesk.' AS reason FROM crm WHERE is_authoritative IS NULL
UNION ALL
SELECT 'support_entitlement' AS table_name, tier_code AS record_key, 'grantsEscalationRight' AS property_name, NULL AS open_question, 'Not stated for PREMIUM. C-12 settles STANDARD (false) only.' AS reason FROM support_entitlement WHERE grants_escalation_right IS NULL;

-- The action for every ontology attribute, resolved to one of the three.
-- SCAN rows have no single action: the pipeline decides per detected span.
CREATE VIEW v_attribute_masking AS
SELECT c.class_name,
       a.property_name,
       c.table_name,
       a.column_name,
       r.handling,
       r.entity_type,
       CASE WHEN r.handling = 'SCAN' THEN NULL
            ELSE COALESCE(e.action_code, r.action_code) END AS action_code,
       CASE WHEN r.handling = 'SCAN' THEN 'Scan per span'
            ELSE act.action_label END AS action_label,
       r.rationale,
       r.status
FROM ont_attribute a
JOIN ont_class c ON c.class_id = a.class_id
LEFT JOIN mask_attribute_rule r ON r.class_id = a.class_id AND r.property_name = a.property_name
LEFT JOIN mask_entity_type e ON e.entity_type = r.entity_type
LEFT JOIN mask_action act ON act.action_code = COALESCE(e.action_code, r.action_code);

-- Every masker entity type with its action and the ontology element it denotes.
CREATE VIEW v_entity_type_masking AS
SELECT e.entity_type,
       act.action_label,
       e.confidence_threshold,
       e.arbitration_precedence,
       c.class_name AS bound_class,
       e.bound_property_name AS bound_property,
       e.binding_gap
FROM mask_entity_type e
JOIN mask_action act ON act.action_code = e.action_code
LEFT JOIN ont_class c ON c.class_id = e.bound_class_id;

-- Ontology vocabulary the masker does not explicitly protect. A term here is
-- not necessarily masked: it is only at risk if NER happens to tag it.
CREATE VIEW v_unprotected_ontology_vocabulary AS
SELECT v.class_id, v.individual_code, v.term
FROM (
    SELECT class_id, individual_code, individual_code AS term FROM ont_individual
    UNION
    SELECT class_id, individual_code, label FROM ont_individual WHERE label IS NOT NULL
    UNION
    SELECT class_id, individual_code, alias_term FROM ont_alias WHERE individual_code IS NOT NULL
) v
WHERE v.class_id IN ('sup:Region', 'sup:SeverityLevel', 'sup:SupportEntitlement', 'sup:Product')
  AND NOT EXISTS (SELECT 1 FROM mask_protected_term p WHERE LOWER(p.term) = LOWER(v.term));
